                    <label class="control-label">Orbital Distance (AU)</label>
                    <div class="slider-container">
                        <input type="range" id="distanceSlider" min="50" max="300" value="150">
                        <span id="distanceValue" class="value-display">1.5</span>
                    </div>
                </div>
            </div>

