                <button id="startBtn"><i class="fas fa-play"></i> Start Simulation</button>
                <button id="resetBtn"><i class="fas fa-redo"></i> Reset</button>
                <button id="stableBtn"><i class="fas fa-circle"></i> Set Stable Orbit</button>
                <button id="decayBtn"><i class="fas fa-arrow-down"></i> Simulate Decay</button>
            </div>
        </div>

